import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { TraceMap, originalPositionFor } from '@jridgewell/trace-mapping';
import { orderedCpuSamples } from '../scripts/benchmarks/cpu-profile.mjs';

const root = process.cwd();
const maps = new Map();
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const mapArtifacts = [];
function annotate(frame) {
  if (!frame.url?.includes('/node_modules/')) return frame;
  const rel = new URL(frame.url).pathname.slice(1);
  if (!maps.has(rel)) {
    const mapPath = path.join(root, rel + '.map');
    if (!fs.existsSync(mapPath)) maps.set(rel, null);
    else {
      const bytes = fs.readFileSync(mapPath);
      maps.set(rel, new TraceMap(JSON.parse(bytes)));
      mapArtifacts.push({ path: rel + '.map', sha256: hash(bytes), bytes: bytes.length });
    }
  }
  const map = maps.get(rel);
  if (!map) return frame;
  const pos = originalPositionFor(map, { line: frame.lineNumber + 1, column: frame.columnNumber });
  return { ...frame, originalFile: pos.source ? path.relative(root, path.resolve(path.dirname(path.join(root, rel)), pos.source)).replaceAll('\\', '/') : null,
    originalLine: pos.line, originalColumn: pos.column, originalName: pos.name };
}
const families = {
  materialDirty: node => /_markAllSubMeshesAsDirty/.test(node.callFrame.functionName),
  prepareEffect: node => node.callFrame.functionName === '_prepareEffect',
  skeletonPrepare: node => node.callFrame.functionName === 'prepare' && /skeleton/i.test(annotate(node.callFrame).originalFile ?? ''),
  animation: node => /^(?:_animate|goToFrame|_interpolate)$/.test(node.callFrame.functionName) && /(?:animation|animatable)/i.test(annotate(node.callFrame).originalFile ?? node.callFrame.url),
  cloneOrInstantiate: node => /(?:clone|instantiateModelsToScene|createInstance)/i.test(node.callFrame.functionName),
};
function callerFamilies(profile) {
  const nodes = new Map(profile.nodes.map(node => [node.id, node]));
  const parents = new Map(profile.nodes.flatMap(node => (node.children ?? []).map(child => [child, node.id])));
  const contexts = new Map();
  const getContexts = id => {
    if (contexts.has(id)) return contexts.get(id);
    const stack = [];
    for (let cursor = id; cursor !== undefined; cursor = parents.get(cursor)) stack.push(nodes.get(cursor));
    const value = {};
    for (const [family, matches] of Object.entries(families)) {
      const index = stack.findIndex(matches);
      if (index === -1) continue;
      const tail = stack.slice(index);
      const app = tail.findIndex(node => node.callFrame.url.includes('/src/'));
      const lastApp = tail.findLastIndex(node => node.callFrame.url.includes('/src/'));
      const frames = tail.slice(0, app === -1 ? Math.min(10, tail.length) : lastApp + 1).map(node => annotate(node.callFrame));
      value[family] = frames;
    }
    contexts.set(id, value);
    return value;
  };
  const groups = Object.fromEntries(Object.keys(families).map(family => [family, new Map()]));
  let previous = profile.startTime;
  for (const sample of orderedCpuSamples(profile)) {
    const ms = (sample.at - previous) / 1000; previous = sample.at;
    for (const [family, stack] of Object.entries(getContexts(sample.id))) {
      const key = JSON.stringify(stack);
      const group = groups[family].get(key) ?? { stack, inclusiveMs: 0, samples: 0 };
      group.inclusiveMs += ms; group.samples++;
      groups[family].set(key, group);
    }
  }
  return Object.fromEntries(Object.entries(groups).map(([family, groups]) => [family,
    [...groups.values()].sort((a, b) => b.inclusiveMs - a.inclusiveMs)]));
}
const out = { schemaVersion: 1, date: '2026-10-11', capture: 'public/data/benchmarks/results/2026-10-11-draw-cpu',
  limitations: ['Inclusive functions and families overlap; sampled time is attribution, not measured savings or call counts.',
    'Caller family patterns are diagnostic filters; non-matching clone/setup work is not included.',
    'Original source positions are decoded from the saved Vite dependency maps; application URLs retain generated positions.'],
  phases: [], mapArtifacts };
for (const [number, backend] of [[1, 'webgl2'], [2, 'webgpu']]) {
  const name = `${number}-${backend}`, dir = path.join(root, out.capture, name);
  const meta = JSON.parse(fs.readFileSync(path.join(dir, 'run.json')));
  const report = JSON.parse(fs.readFileSync(path.join(dir, 'timedemo.json')));
  for (const phase of report.fixture.segments) {
    const base = `${name}-${phase.name}`;
    const summary = JSON.parse(fs.readFileSync(path.join(dir, `${base}-summary.json`)));
    const profile = JSON.parse(fs.readFileSync(path.join(dir, `${base}.cpuprofile`)));
    const slowPath = path.join(dir, `${base}-slow-frames.json`);
    const slow = fs.existsSync(slowPath) ? JSON.parse(fs.readFileSync(slowPath)) : null;
    const entry = { backend, phase: phase.name, valid: meta.valid, source: meta.sourceBefore,
      frames: summary.frames, durationMs: summary.summary.durationMs, sampledMs: summary.summary.sampledMs,
      topSelf: summary.summary.bySelf.slice(0, 30).map(annotate),
      selectedFunctions: summary.summary.byInclusive.filter(frame => /(?:isReady|bindForSubMesh|_prepareEffect|_markAllSubMeshes|_evaluateActiveMeshes|computeWorldMatrix|_computeTransformMatrices|prepare|_animate|goToFrame|clone|instantiateModels|createInstance|_processRendering|drawElements|_bindBones)/i.test(frame.functionName)).map(annotate),
      callerFamilies: callerFamilies(profile),
      slowFrames: slow ? { thresholdMs: slow.thresholdMs, selectedFrames: slow.selectedFrames.length,
        sampledMs: slow.summary.sampledMs, topSelf: slow.summary.bySelf.slice(0, 30).map(annotate) } : null,
    };
    out.phases.push(entry);
    const brief = { backend, phase: phase.name, frames: entry.frames,
      topSelf: entry.topSelf.slice(0, 12).map(f => ({ name: f.functionName, source: f.originalFile, percent: f.selfPercent, msPerFrame: f.selfMsPerFrame })),
      callers: Object.fromEntries(Object.entries(entry.callerFamilies).map(([family, groups]) => [family, groups.slice(0, 3).map(group => ({ ms: group.inclusiveMs,
        stack: group.stack.map(f => `${f.functionName}@${f.originalFile ?? f.url}`) }))])) };
    console.log(JSON.stringify(brief, null, 2));
  }
}
fs.writeFileSync(path.join(root, '.cache/draw-cpu-analysis-2026-10-11.json'), JSON.stringify(out, null, 2) + '\n');

