import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';
import { summarizeOutlineSeries } from '../scripts/benchmarks/outline-comparison.mjs';

const workspace = process.cwd();
const root = path.join(workspace, '.cache/outline-quick-2026-10-11');
const assets = path.join(root, 'public/data/benchmarks');
const baseId = 'player-outline-proxy-v1-044283d539ef8e1f-0';
const baseBytes = await fs.readFile(path.join(assets, baseId, 'manifest.json'));
const base = JSON.parse(baseBytes);
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const baseHash = digest(baseBytes);
if (base.profile.requiredCvars.cl_player_outline !== 1 || base.profile.requiredCvars.cl_player_outline_proxy !== 0) throw Error('Wrong base');
const demo = await fs.readFile(path.join(assets, baseId, 'demo.shagdemo'));
if (digest(demo) !== base.demo.sha256) throw Error('Wrong demo hash');
const variants = [0, 30].map(rate => {
  const fixture = structuredClone(base);
  fixture.id = `player-pose-v1-${baseHash.slice(0, 16)}-${rate}`;
  fixture.profile.requiredCvars.cl_player_pose_hz = rate;
  fixture.provenance.derivedProfile = { generator: '.cache/run-pose-comparison-2026-10-11.mjs', version: 1,
    baseFixture: baseId, baseManifestSha256: baseHash, change: { cl_player_pose_hz: rate } };
  return fixture;
});
for (const fixture of variants) {
  const dir = path.join(assets, fixture.id), bytes = JSON.stringify(fixture, null, 2);
  try { await fs.mkdir(dir); }
  catch(error) {
    if(error.code !== 'EEXIST') throw error;
    if (await fs.readFile(path.join(dir, 'manifest.json'), 'utf8') !== bytes || digest(await fs.readFile(path.join(dir, 'demo.shagdemo'))) !== base.demo.sha256) throw Error('Existing fixture differs');
    continue;
  }
  await fs.writeFile(path.join(dir, 'manifest.json'), bytes);
  await fs.writeFile(path.join(dir, 'demo.shagdemo'), demo);
}
const indexPath = path.join(assets, 'index.json'), index = JSON.parse(await fs.readFile(indexPath));
await fs.writeFile(indexPath, JSON.stringify([...new Set([...index, ...variants.map(v => v.id)])].sort(), null, 2));
const relativeOut = 'public/data/benchmarks/results/2026-10-11-pose-corrected';
const out = path.join(root, relativeOut);
await fs.mkdir(out);
const series = { schemaVersion: 1, axis: 'cl_player_pose_hz', baseFixture: baseId, baseManifestSha256: baseHash,
  generatorSha256: digest(await fs.readFile(path.join(workspace, '.cache/run-pose-comparison-2026-10-11.mjs'))),
  variants, plan: ['webgl2', 'webgpu'].flatMap(backend => [0, 30].map(rate => ({ backend, rate }))), attempts: [], summary: {},
  limitations: ['One timing-only pair per backend, pose 0 first, fresh visible sessions; order effects and repeatability unmeasured.',
    'Same recording/route; normal player outlines on, outline proxy off.',
    'Uses existing comparison source/workload/profile gates; never retries rejected stalls.'] };
await fs.writeFile(path.join(out, 'plan.json'), JSON.stringify(series, null, 2));
for (const [index, item] of series.plan.entries()) {
  const fixture = variants.find(v => v.profile.requiredCvars.cl_player_pose_hz === item.rate);
  const directory = path.join(out, `${String(index + 1).padStart(2, '0')}-${item.backend}-pose-${item.rate}`);
  console.log(`[pose] ${index + 1}/4: ${item.backend}, pose ${item.rate}`);
  const exitCode = await new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [path.join(root, 'scripts/benchmarks/profile-timedemo.mjs'), '--timing-only',
      '--backends', item.backend, '--fixture', fixture.id, '--out', directory], { cwd: root, stdio: 'inherit', windowsHide: true });
    child.on('error', reject); child.on('exit', code => resolve(code ?? 1));
  });
  const folder = path.join(directory, `1-${item.backend}`);
  const read = async (base, file) => fs.readFile(path.join(base, file), 'utf8').then(JSON.parse).catch(() => null);
  const captureSeries = await read(directory, 'series.json');
  const meta = await read(folder, 'run.json'), report = await read(folder, 'timedemo.json');
  series.attempts.push({ backend: item.backend, outline: item.rate, rate: item.rate, repetition: 1,
    fixture: fixture.id, directory: path.relative(root, directory), exitCode, harnessSha256: captureSeries?.harnessSha256, meta, report });
  // Reuse the existing source/browser/route/profile/workload gates, changing only
  // the varied numeric CVar. The generic helper's legacy group label is renamed.
  series.summary = Object.fromEntries(Object.entries(summarizeOutlineSeries(series.attempts, 1, 'cl_player_pose_hz'))
    .map(([key, group]) => [key.replace(':outline-', ':pose-'), group]));
  await fs.writeFile(path.join(out, 'series.json'), JSON.stringify(series, null, 2));
}
console.log(JSON.stringify(Object.fromEntries(Object.entries(series.summary).map(([key, group]) => [key,
  { validRuns: group.validRuns, rejectedRuns: group.rejectedRuns, wholeTour: group.phases['whole-tour'] }])), null, 2));
if (Object.values(series.summary).some(group => !group.enoughRuns)) process.exitCode = 1;
